import subprocess,re,sys,os,tempfile
EXE='/workspace/executable'
def run(content, args=(), name=None, binary=False):
    d='/tmp/geom-agent/w'; os.makedirs(d,exist_ok=True)
    inf=os.path.join(d,(name or 'in')+'.txt')
    if binary: open(inf,'wb').write(content)
    else: open(inf,'w').write(content)
    out=os.path.join(d,(name or 'in')+'.svg')
    if os.path.exists(out): os.remove(out)
    p=subprocess.run([EXE,inf,out,'--svg']+list(args),capture_output=True,text=True)
    svg=open(out).read() if os.path.exists(out) else None
    return p,svg
def dims(svg):
    if svg is None: return None
    w=re.search(r"^    width='(\d+)'",svg,re.M); h=re.search(r"^    height='(\d+)'",svg,re.M)
    return int(w.group(1)),int(h.group(1))
def info(content,args=(),name=None,binary=False):
    p,svg=run(content,args,name,binary)
    d=dims(svg)
    sw=re.search(r"<g stroke-width='([^']*)'",svg) if svg else None
    fs=sorted(set(re.findall(r"font-size='([^']*)'",svg))) if svg else []
    return dict(rc=p.returncode,dims=d,sw=sw.group(1) if sw else None,fs=fs,
                stderr=p.stderr.strip(),stdout=p.stdout.strip(),svg=svg)
