def grid(content,args=(),name=None,binary=False,scale=1.0):
    """returns (cols,rows) inferred from image dims, or error string"""
    i=info(content,args,name,binary)
    if i['dims'] is None:
        return ('ERR',i['rc'],(i['stderr'].splitlines() or [''])[0][:100])
    cw=int(10*scale); ch=int(14*scale)
    w,h=i['dims']
    return (w//cw-4, h//ch-4, w, h)
